export interface UserTokenAuth {
    type: 'basic'
    token?: string | undefined
    cookie?: string | undefined
}

export interface OAuthAuth {
    type: 'oauth'
    token: string
}

export type ResolvedAuth = UserTokenAuth | OAuthAuth

interface BaseCredential {
    instanceUrl: URL
}

export type UserTokenCredential = BaseCredential & UserTokenAuth

export type OAuthCredential = BaseCredential & OAuthAuth

export type Credential = UserTokenCredential | OAuthCredential

export class LazyCredential {
    private resolveAuthPromise?: Promise<ResolvedAuth>

    constructor(
        private readonly instanceUrl: URL,
        private readonly authResolver: () => Promise<ResolvedAuth> | ResolvedAuth
    ) {}

    public getUrl(): URL {
        return this.instanceUrl
    }

    private resolveAuth(): Promise<ResolvedAuth> {
        this.resolveAuthPromise ??= Promise.resolve(this.authResolver())
        return this.resolveAuthPromise
    }

    public async getSysParmCk(): Promise<string> {
        const auth = await this.resolveAuth()
        return auth.type === 'basic' ? (auth.token ?? '') : ''
    }

    public async getHeaders(): Promise<Record<string, string>> {
        const resolvedAuth = await this.resolveAuth()
        const headers: Record<string, string> = {}

        switch (resolvedAuth.type) {
            case 'basic':
                if (resolvedAuth.token) {
                    headers['X-UserToken'] = resolvedAuth.token
                }
                if (resolvedAuth.cookie) {
                    headers['Cookie'] = resolvedAuth.cookie
                }
                break
            case 'oauth':
                headers['Authorization'] = `Bearer ${resolvedAuth.token}`
                break
        }

        return headers
    }
}
